import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {COLORWAYS,PALETTES,paletteAt,easeInOut,mountWalletMotion} from '../public/assets/home-preview/wallet-motion.js';

test('all ten web palettes match native Swift output to Float precision',()=>{
  // Fixture generated by executing OathColorway.swift palette code with Foundation on the host.
  const native=JSON.parse(readFileSync(new URL('./fixtures/wallet-native-palettes.json',import.meta.url)));
  assert.equal(COLORWAYS.length,10);
  PALETTES.forEach((palette,i)=>palette.forEach((x,j)=>assert.ok(Math.abs(x-native[i][j])<1e-7)));
});
test('palette holds, transitions continuously in 0.5s, and wraps without restarting motion',()=>{
  assert.equal(paletteAt(0).name,'cobalt');
  assert.deepEqual(paletteAt(0).values,PALETTES[0]);
  assert.deepEqual(paletteAt(5).values,PALETTES[0]);
  assert.deepEqual(paletteAt(5.5).values,PALETTES[1]);
  assert.ok(Math.abs(easeInOut(.5)-.5)<1e-5);
  paletteAt(5.25).values.forEach((x,i)=>assert.ok(Math.abs(x-(PALETTES[0][i]+PALETTES[1][i])/2)<1e-5));
  assert.deepEqual(paletteAt(55).values,PALETTES[0]);
  paletteAt(55-1e-6).values.forEach((x,i)=>assert.ok(Math.abs(x-PALETTES[0][i])<1e-6));
});

function harness(t,{reduced=false,unavailable=false}={}){
  const target=()=>({listeners:new Map(),style:{},dataset:{},addEventListener(k,f){this.listeners.set(k,f);},removeEventListener(k){this.listeners.delete(k);},emit(k,event={}){this.listeners.get(k)?.(event);},setAttribute(){},remove(){this.removed=true;}});
  const button=target(),media=Object.assign(target(),{matches:reduced}),doc=Object.assign(target(),{hidden:false,createElement:()=>button});
  let observer,draws=0,time=0,next=0,fetches=0,released=0;
  const pending=new Map();
  const gl={createShader:()=>({}),shaderSource(){},compileShader(){},getShaderParameter:()=>true,createProgram:()=>({}),attachShader(){},linkProgram(){},getProgramParameter:()=>true,createBuffer:()=>({}),bindBuffer(){},bufferData(){},getUniformLocation:(_,key)=>key,useProgram(){},getAttribLocation:()=>0,enableVertexAttribArray(){},vertexAttribPointer(){},viewport(){},uniform2f(){},uniform1f(_,value){time=value;},uniform3fv(){},drawArrays(){draws++;},deleteBuffer(){released++;},deleteProgram(){released++;},deleteShader(){released++;}};
  const canvas=Object.assign(target(),{getContext:()=>unavailable?null:gl,closest:()=>({append(){}})});
  t.mock.method(globalThis,'fetch',async()=>{fetches++;return {ok:true,text:async()=>''};});
  for(const [key,value] of Object.entries({document:doc,window:{matchMedia:()=>media},IntersectionObserver:class{constructor(cb){observer=this;this.cb=cb;}observe(){}disconnect(){this.disconnected=true;}},requestAnimationFrame:cb=>{pending.set(++next,cb);return next;},cancelAnimationFrame:id=>pending.delete(id)})){
    const old=Object.getOwnPropertyDescriptor(globalThis,key);
    Object.defineProperty(globalThis,key,{value,configurable:true,writable:true});
    t.after(()=>old?Object.defineProperty(globalThis,key,old):delete globalThis[key]);
  }
  const dispose=mountWalletMotion(canvas);
  return {canvas,button,media,doc,dispose,visible(value){observer.cb([{isIntersecting:value}]);},async settled(){await new Promise(resolve=>setImmediate(resolve));},step(now){const callbacks=[...pending.values()];pending.clear();callbacks.forEach(cb=>cb(now));},get state(){return {draws,time,pending:pending.size,fetches,released,disconnected:observer.disconnected};}};
}
test('renderer is lazy, throttled, pauses offscreen/hidden/user pause, and fully cleans up',async t=>{
  const h=harness(t);assert.equal(h.state.fetches,0);
  h.visible(true);await h.settled();assert.equal(h.canvas.dataset.motion,'ready');assert.equal(h.state.pending,1);
  h.step(0);const draws=h.state.draws;h.step(16);assert.equal(h.state.draws,draws);
  h.step(40);assert.equal(h.state.draws,draws+1);assert.equal(h.state.time,.04);
  h.visible(false);assert.equal(h.state.pending,0);
  h.visible(true);h.step(100000);assert.equal(h.state.time,.04);
  h.doc.hidden=true;h.doc.emit('visibilitychange');assert.equal(h.state.pending,0);
  h.doc.hidden=false;h.doc.emit('visibilitychange');h.step(200000);assert.equal(h.state.time,.04);
  h.button.emit('click');assert.equal(h.state.pending,0);assert.equal(h.button.textContent,'Resume animation');
  h.button.emit('click');assert.equal(h.state.pending,1);
  h.media.matches=true;h.media.emit('change');assert.equal(h.state.pending,0);
  h.dispose();assert.equal(h.state.pending,0);assert.ok(h.state.disconnected);assert.ok(h.button.removed);assert.equal(h.state.released,4);
  assert.equal(h.doc.listeners.size,0);assert.equal(h.media.listeners.size,0);assert.equal(h.canvas.listeners.size,0);
});
test('reduced motion presents a still frame without starting animation',async t=>{
  const h=harness(t,{reduced:true});h.visible(true);await h.settled();assert.equal(h.state.draws,1);assert.equal(h.canvas.dataset.colorway,'cobalt');assert.equal(h.state.pending,0);h.dispose();
});
test('unavailable WebGL keeps poster and avoids repeated retries',async t=>{
  const h=harness(t,{unavailable:true});h.visible(true);await h.settled();assert.equal(h.canvas.dataset.motion,'fallback');assert.equal(h.canvas.style.opacity,'0');
  h.visible(false);h.visible(true);assert.equal(h.state.fetches,1);assert.equal(h.state.pending,0);h.dispose();
});
test('context loss shows poster, restoration resumes from paused time',async t=>{
  const h=harness(t);h.visible(true);await h.settled();h.step(0);h.step(100);
  let prevented=false;h.canvas.emit('webglcontextlost',{preventDefault(){prevented=true;}});assert.ok(prevented);assert.equal(h.state.pending,0);assert.equal(h.canvas.style.opacity,'0');
  h.canvas.emit('webglcontextrestored');await h.settled();assert.equal(h.canvas.dataset.motion,'ready');h.step(100000);assert.equal(h.state.time,.1);h.dispose();
});
test('unmount during asynchronous initialization cannot start a renderer',async t=>{
  const h=harness(t);h.visible(true);h.dispose();await h.settled();assert.equal(h.state.draws,0);assert.equal(h.state.pending,0);
});
